let selected=null, accelerated=[],busy=false,history=[];
const $=s=>document.querySelector(s), esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), palette={Red:'#deb2b0',Green:'#b8ceb0',Blue:'#b1c8df',White:'#e7e4da',Multi:'#cfbddc'}, typeIt={Creature:'Creature',Building:'Building',Sorcery:'Spell'};
const ABILITIES = {"Tree of life": "Your green cards cost 1 less time.", "Fireball": "Deal 2 damage to all enemy creatures in one zone.", "Monolith": "Move up to 2 creatures on the battlefield by 1 zone.", "Selective bombing": "Choose a color: all creatures of that color take 2 damage.", "Elf": "May move and attack during the same activation.", "Elf archer": "May attack in its own zone or an adjacent zone.", "Apprentice": "Activate another friendly blue creature.", "Regeneration": "Remove 3 damage, divided among your creatures.", "Time Spiral": "Move all your blue creatures by 1, on the battlefield and the timer.", "WInd of change": "Gain 2 extra actions.", "Final Assault": "Your red creatures gain an extra activation.", "Mystical force": "Choose a color: your creatures of that color gain an activation.", "Rebuilt": "Remove 3 damage, divided among your buildings and castle.", "Harmony": "Advance one of your cards of each color by 1 on your timer.", "Druid": "Take a green creature from the market and place it at time 5.", "Manticore": "Has all colors.", "Phenix": "When it dies, return it to time 3 on your timer.", "Commandant": "Attack equals your red creatures on the battlefield and timer.", "Master of time": "Swap the positions of 2 cards on a timer of your choice.", "Saboteur": "May sacrifice itself to destroy an enemy building in the same zone.", "Mason": "Advance one of your buildings by 1 on your timer.", "Elf scout": "Cost: 5 minus your green creatures on the battlefield and timer (minimum 1).", "Lumberjack": "Remove 1 damage from one of your buildings or your castle.", "Shield leader": "Other friendly creatures in its zone cannot be attacked.", "Decoy": "Your buildings and castle cannot be attacked.", "Necromancer": "Return a creature from your graveyard to time 2.", "Armory": "Your creatures deal 1 extra damage when attacking.", "School of Magic": "Disable an enemy building while this school remains on the battlefield.", "Mercenary": "As an action, your opponent may recruit it at time 2 on their timer.", "Protection Wall": "Must be destroyed before your other buildings and castle.", "Source of growth": "Gain an extra action.", "Secret passages": "All your cards cost 1 less time.", "Manipulator": "Choose the next action of your opponent: recruit or accelerate.", "Magic Shield": "Each attack against your castle deals at most 2 damage.", "Trenches": "Your creatures enter the battlefield in the central zone.", "Outpost": "Whenever a friendly red creature enters, deal 1 damage to an enemy card.", "Dolmen": "Whenever a friendly blue creature enters, advance one of your cards by 1 on your timer.", "Temple of Benediction": "Whenever a friendly white creature enters, heal 1 damage on a friendly creature.", "Magnetic force": "Move a creature of your choice by 1 zone.", "Catapult": "Deal 1 damage to an enemy creature.", "Hospital": "At the start of each of your turns, heal 1 damage on a friendly creature.", "Medicine school": "Your white creatures may use an activation to heal 2 damage.", "Parlement": "Creature stars do not count toward victory for either player.", "Révolution": "All your creatures without stars make an attack."};
function description(d){return ABILITIES[d.name]|| (d.type==='Creature'?'Move one zone or attack.':d.ability)}
function save(){try{localStorage.setItem('light-echoes-v1',JSON.stringify({S,sequence}))}catch{}}
const LEGACY_TEXT = [["Ogni carta giocata va sul timer nella posizione indicata dal costo. Dopo la seconda scelta, le 2 carte rimaste vengono scartate automaticamente.", "Each card goes on your timer at its time cost, or the next higher available position. Each tile holds at most 2 cards. After your second choice, the 2 remaining cards are automatically discarded."], ["La tessera in posizione 1 esce. Inserisci quella esterna in posizione 5: tutte le altre avanzano.", "The tile at position 1 exits. Insert the outside tile at position 5: all the others advance."], ["Il costo in tempo indica la posizione di ingresso: 1 è vicino all’uscita, 5 è più lontano.", "Each tile holds 2 cards. Start at the time cost; if full, use the next available higher position, up to 5. If none is free, the card cannot be played."], ["Importate dall’Excel. I costi mostrati includono gli sconti del giocatore di turno.", "Imported from the spreadsheet. Displayed costs include the current player’s discounts."], [". Ogni carta può attivarsi una volta. Puoi terminare anche senza usarle tutte.", ". Each card may activate once. You may end your turn without using them all."], ["Inserisci la tessera esterna. Le carte in uscita entrano in gioco.", "Insert the outside tile. Cards that exit enter play."], ["Gioco di carte per due giocatori con plance a scorrimento.", "A two-player card game with sliding time boards."], ["Prendi una carta dal mercato oppure accelera 1 o 2 carte.", "Take a market card or accelerate 1 or 2 cards."], ["Usa le carte illuminate, nell’ordine che preferisci.", "Use the highlighted cards in any order."], ["Seleziona le carte sul tuo timer per accelerarle.", "Select cards on your timer to accelerate them."], ["Setup completato. Inizia il primo turno di Giada.", "Setup complete. Jade takes the first turn."], ["Setup: Giada sceglie 2 carte tra le 4 pescate.", "Setup: Jade chooses 2 of the 4 drawn cards."], ["Setup: Ambra sceglie 2 carte tra le 4 pescate.", "Setup: Amber chooses 2 of the 4 drawn cards."], ["Pesca 4 carte, giocane 2 e scarta le altre 2.", "Draw 4 cards, play 2, and discard the other 2."], ["Scegli un’opzione per risolvere l’effetto.", "Choose an option to resolve the effect."], [" carte ricevono un’attivazione aggiuntiva.", " cards gain an extra activation."], ["Azione annullata per un errore. Riprova.", "Action canceled because of an error. Please try again."], ["Seleziona una carta dalla mano iniziale.", "Select a card from your starting hand."], ["Imponi la prossima azione avversaria", "Choose the next enemy action"], ["Sabota un edificio nella stessa zona", "Sabotage a building in the same zone"], ["Cura: scegli dove rimuovere 1 danno", "Heal: choose where to remove 1 damage"], ["Selective bombing: scegli un colore", "Selective bombing: choose a color"], ["Partita salvata su questo browser.", "Game saved in this browser."], ["Muovi di una zona oppure attacca.", "Move one zone or attack."], ["Il campo attende le tue creature.", "The battlefield awaits your creatures."], ["Druid: creatura verde dal mercato", "Druid: green creature from the market"], ["Monolith: muovi una creatura di 1", "Monolith: move a creature by 1"], [" recluta il Mercenary avversario.", " recruits the enemy Mercenary."], ["Il castello avversario è caduto.", "The enemy castle has fallen."], ["Nessuna azione possibile · passa", "No action available · pass"], ["Mystical force: scegli un colore", "Mystical force: choose a color"], ["Disattiva un edificio avversario", "Disable an enemy building"], ["Catapult: 1 danno a una creatura", "Catapult: deal 1 damage to a creature"], ["Riporta una creatura al tempo 2", "Return a creature to time 2"], ["Non attivabile in questa fase.", "Cannot activate in this phase."], ["Già attivata in questo turno.", "Already activated this turn."], ["Dolmen: avanza una carta di 1", "Dolmen: advance a card by 1"], ["Recluta Mercenary · 1 azione", "Recruit Mercenary · 1 action"], ["Attiva un’altra creatura blu", "Activate another blue creature"], ["2 giocatori · stesso schermo", "2 players · same screen"], ["Iniziare una nuova partita?", "Start a new game?"], ["Continua la partita attuale", "Continue the current game"], ["Nessuna abilità aggiuntiva.", "No additional ability."], ["Phenix rinasce al tempo 3.", "Phenix returns at time 3."], ["Seconda carta da scambiare", "Second card to swap"], [" scarta le altre 2 carte.", " discards the other 2 cards."], ["Nessun bersaglio valido: ", "No valid target: "], ["Outpost: infliggi 1 danno", "Outpost: deal 1 damage"], ["Fireball: scegli una zona", "Fireball: choose a zone"], ["Nessuna carta schierata.", "No cards deployed."], ["Prima carta da scambiare", "First card to swap"], [" usa la propria abilità.", " uses its ability."], ["Dieci stelle sul campo.", "Ten stars on the battlefield."], [": scorrimento, simbolo ", ": slide, symbol "], ["Scegli il bersaglio di ", "Choose a target for "], ["Avanza un edificio di 1", "Advance a building by 1"], ["Prepara le tue carte, ", "Prepare your cards, "], ["Annulla ultima azione", "Undo last action"], ["PRIMA DEL PRIMO TURNO", "BEFORE THE FIRST TURN"], ["Scegli le tue 2 carte", "Choose your 2 cards"], ["La tua mano iniziale", "Your starting hand"], ["Manipulator impone: ", "Manipulator requires: "], ["In attesa sul timer.", "Waiting on the timer."], ["Dai vita alle carte", "Bring your cards to life"], ["prendere una carta.", "take a card."], ["/2 carte di 2 spazi", "/2 cards by 2 spaces"], [" esce dal timer di ", " leaves the timer of "], ["Il tavolo del tempo", "The time board"], ["IL TAVOLO DEL TEMPO", "THE TIME BOARD"], ["Ingresso al tempo ", "Enters at time "], ["Gioca sul timer · ", "Play on timer · "], [" durante il setup.", " during setup."], [" carte di 2 spazi.", " cards by 2 spaces."], ["Prendere una carta", "Take a card"], ["Muovi una creatura", "Move a creature"], ["Sì, nuova partita", "Yes, start a new game"], ["Prepara il futuro", "Prepare for the future"], ["SETUP · GIOCATORE", "SETUP · PLAYER"], ["accelerare carte.", "accelerate cards."], ["Testo originale: ", "Original text: "], [" viene distrutto.", " is destroyed."], ["01 · SCORRIMENTO", "01 · SLIDE"], ["03 · ATTIVAZIONE", "03 · ACTIVATE"], ["vince la partita", "wins the game"], ["Simbolo attivo: ", "Active symbol: "], ["Prendi e prepara", "Take and prepare"], ["Torna alle carte", "Back to cards"], ["A te la mossa, ", "Your move, "], ["Termina turno →", "End turn →"], ["Il tempo scorre", "Time moves on"], ["Muovi di 1 zona", "Move 1 zone"], ["Muovi e attacca", "Move and attack"], ["Harmony: carta ", "Harmony: card color "], ["Scegli il timer", "Choose a timer"], ["SIMBOLO ATTIVO", "ACTIVE SYMBOL"], ["Fai scorrere →", "Slide tiles →"], ["TERRA DI GIADA", "JADE HOME ZONE"], ["TERRA DI AMBRA", "AMBER HOME ZONE"], ["Scegli ancora ", "Choose "], [" si muove in ", " moves to "], ["Nuova partita", "New game"], ["Gioca ancora", "Play again"], ["LA TUA MOSSA", "YOUR MOVE"], ["Il tuo timer", "Your timer"], ["Cura 2 danni", "Heal 2 damage"], ["02 · AZIONE", "02 · ACTION"], ["Pool comune", "Shared pool"], ["/ 2 giocate", "/ 2 played"], ["Usa abilità", "Use ability"], ["Le 52 carte", "All 52 cards"], ["Istantanea", "Instant"], ["· inattivo", "· disabled"], ["Il mercato", "The market"], [" al tempo ", " at time "], [" accelera ", " accelerates "], [" infligge ", " deals "], [" damage a ", " damage to "], ["Zona Giada", "Jade zone"], ["Zona Ambra", "Amber zone"], ["zona Giada", "Jade zone"], ["zona Ambra", "Amber zone"], ["Accelerare", "Accelerate"], ["Carte · 52", "Cards · 52"], ["in attesa", "waiting"], ["in arrivo", "incoming"], ["FRONTIERA", "FRONTIER"], ["nel mazzo", "in deck"], ["3 tessere", "3 tiles"], ["2 tessere", "2 tiles"], ["1 tessera", "1 tile"], [" prepara ", " prepares "], ["Accelera ", "Accelerate "], ["Creatura", "Creature"], ["Edificio", "Building"], ["di turno", "playing"], ["· uscita", "· exit"], ["Castello", "Castle"], ["CRONACA", "GAME LOG"], ["Attacca", "Attack"], [" vince!", " wins!"], [" danni", " damage"], ["Muovi ", "Move "], ["Centro", "Center"], ["centro", "center"], ["Turno ", "Turn "], ["Regole", "Rules"], ["Chiudi", "Close"], ["Magia", "Spell"], ["FUORI", "OUTSIDE"], ["TURNO", "TURN"], [" DI 2", " OF 2"], [" vite", " life"], ["Giada", "Jade"], ["Ambra", "Amber"]];
function translateSavedLog(t){t=t.replace("La partita comincia. Giada inserisce la tessera esterna.","The game begins. Jade inserts the outside tile.");for(const [a,b] of LEGACY_TEXT)t=t.split(a).join(b);return t.replaceAll(" damage a "," damage to ")}
try{let x=JSON.parse(localStorage.getItem('light-echoes-v1'));if(x?.S?.version===1){S=x.S;S.log=S.log.map(translateSavedLog);sequence=x.sequence}else fresh()}catch{fresh()}
async function run(fn){if(busy||S.winner!==null)return;history.push(JSON.stringify({S,sequence}));if(history.length>30)history.shift();busy=true;render();try{await fn()}catch(e){console.error(e);let previous=JSON.parse(history.pop());S=previous.S;sequence=previous.sequence;log('Action canceled because of an error. Please try again.')}busy=false;selected=null;accelerated=[];save();render()}
function choose(title,items,label){return new Promise(resolve=>{render();let m=$('#modal');$('#modalBody').innerHTML='<h2>'+esc(title)+'</h2><p>Choose an option to resolve the effect.</p><div class="choices">'+items.map((x,i)=>'<button data-choice="'+i+'">'+esc(label(x))+'</button>').join('')+'</div>';m.querySelector('.close').hidden=true;m.oncancel=e=>e.preventDefault();m.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{m.close();m.oncancel=null;m.querySelector('.close').hidden=false;resolve(items[Number(b.dataset.choice)])});m.showModal()})}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').querySelector('.close').hidden=false;$('#modal').showModal()}
async function newGame(){if(busy)return;let yes=await choose('Start a new game?',[false,true],v=>v?'Yes, start a new game':'Continue the current game');if(yes){fresh();history=[];selected=null;accelerated=[];save();render()}}
function undo(){if(busy||!history.length)return;let x=JSON.parse(history.pop());S=x.S;S.log=S.log.map(translateSavedLog);sequence=x.sequence;selected=null;accelerated=[];save();render()}
function find(uid){return [...S.board,...waiting(0),...waiting(1)].find(c=>c.uid===uid)}
function selectMarket(id){if(busy)return;selected={market:id};accelerated=[];render()}
function selectUnit(uid){if(busy)return;selected={uid};render()}
function toggleTime(uid){if(busy)return;selected={uid};let c=find(uid);if(S.phase==='action'&&c.owner===S.p){if(accelerated.includes(uid))accelerated=accelerated.filter(x=>x!==uid);else if(accelerated.length<2)accelerated.push(uid)}render()}
function cardHTML(id,click=true){let d=CARDS[id],c={id};return '<button class="card '+(selected?.market===id?'selected':'')+'" style="--cardColor:'+palette[d.color]+'" '+(click?'onclick="selectMarket('+id+')"':'onclick="detail('+id+')"')+'><div class="cardtop"><span>'+esc(d.color)+'</span><b>◷ '+cost(id,S.p)+'</b></div><h3>'+esc(d.name)+'</h3><span class="kind">'+typeIt[d.type]+' · '+speed(c)+'</span><p>'+esc(description(d))+'</p><div class="stats"><span>'+(d.type==='Creature'?'⚔ '+d.attack+'　':'')+(d.life?'♥ '+d.life:'Instant')+'</span><span>★ '+d.stars+'</span></div></button>'}
function track(p){let pl=S.players[p];return '<div class="player '+(p===1?'enemy':'')+'"><strong>'+NAMES[p]+' <span class="badge">'+(p===S.p?'playing':'waiting')+'</span></strong><div class="scores"><span>♥ '+pl.hp+' / 10</span><span>★ '+stars(p)+' / 10</span><span class="muted">'+waiting(p).length+' incoming</span></div></div><div class="track">'+pl.timer.map((t,i)=>'<div class="tile"><div class="tilehead"><span>'+ (i+1)+' '+(i===0?'· exit':'')+'</span><span class="symbol">'+SIGNS[t.sign]+' <small>'+t.sign+'</small></span></div><span class="tile-capacity">'+t.cards.length+'/2</span>'+t.cards.map(c=>'<button class="mini '+(accelerated.includes(c.uid)?'selected':'')+'" style="--cardColor:'+palette[def(c).color]+'" onclick="toggleTime('+c.uid+')">'+esc(def(c).name)+'</button>').join('')+'</div>').join('')+'<div class="tile out"><div class="tilehead">OUTSIDE<span class="symbol">'+SIGNS[pl.outside]+' <small>'+pl.outside+'</small></span></div><small>ACTIVE SYMBOL</small></div></div>'}
function unitHTML(c){return '<button class="unit '+(c.owner===1?'enemy ':'')+(eligible(c)?'ready':'')+'" style="--cardColor:'+palette[def(c).color]+'" onclick="selectUnit('+c.uid+')"><strong>'+esc(def(c).name)+'</strong><span class="meta">'+NAMES[c.owner]+' · '+SIGNS[speed(c)]+' '+speed(c)+(active(c)?'':' · disabled')+'</span><span class="stats"><span>'+(creature(c)?'⚔ '+attackValue(c)+'　':'')+'♥ '+(def(c).life-c.damage)+'/'+def(c).life+'</span><span>★ '+def(c).stars+'</span></span></button>'}
function render(){if(S.phase==='setup'){renderSetup();return}let phase={slide:['01 · SLIDE','Insert the outside tile. Cards that exit enter play.'],action:['02 · ACTION','Take a market card or accelerate 1 or 2 cards.'],activate:['03 · ACTIVATE','Use the highlighted cards in any order.']}, info=phase[S.phase];$('#app').innerHTML=(S.winner!==null?'<div class="win"><h2>'+NAMES[S.winner]+' wins the game</h2><p>'+ (stars(S.winner)>=10?'Ten stars on the battlefield.':'The enemy castle has fallen.')+'</p><button onclick="newGame()">Play again</button></div>':'')+'<div class="turnbar"><div><span class="phase">TURN '+S.turn+' / '+info[0]+'</span><h2>Your move, '+NAMES[S.p]+'.</h2><p>'+info[1]+'</p></div>'+(S.phase==='slide'?'<button class="primary" onclick="run(slide)" '+(busy?'disabled':'')+'>Slide tiles →</button>':S.phase==='activate'?'<button class="primary" onclick="run(async()=>endTurn())" '+(busy?'disabled':'')+'>End turn →</button>':'<span class="badge">'+S.actions+' action'+(S.actions===1?'':'s')+'</span>')+'</div><div class="layout"><section class="table">'+track(1)+'<div class="zoneboard">'+[2,1,0].map(z=>'<div class="zone"><div class="zoneLabel"><b>0'+(z+1)+'</b>'+['JADE HOME ZONE','FRONTIER','AMBER HOME ZONE'][z]+'</div><div class="units">'+(S.board.filter(c=>c.zone===z).map(unitHTML).join('')||'<span class="empty">'+(z===1?'The battlefield awaits your creatures.':'No cards deployed.')+'</span>')+'</div></div>').join('')+'</div>'+track(0)+'<div class="sectionhead"><h2>The market</h2><span>Shared pool · '+S.deck.length+' in deck</span></div><div class="market">'+S.market.map(id=>cardHTML(id)).join('')+'</div><div class="legend"><span>ϟ Fast · 3 tiles</span><span>◈ Medium · 2 tiles</span><span>◷ Slow · 1 tile</span></div></section><aside><span class="eyebrow">YOUR MOVE</span><h2>'+{slide:'Time moves on',action:'Prepare for the future',activate:'Bring your cards to life'}[S.phase]+'</h2>'+side()+'<div class="log"><span class="eyebrow">GAME LOG</span>'+S.log.slice(0,7).map(l=>'<p>'+esc(l)+'</p>').join('')+'</div><button onclick="undo()" '+(!history.length||busy?'disabled':'')+'>↶ Undo last action</button><div class="footer">Game saved in this browser.</div></aside></div>';if(busy||S.winner!==null)$('#app').querySelectorAll('button').forEach(b=>{if(!b.getAttribute('onclick')?.includes('newGame')&&!b.getAttribute('onclick')?.includes('undo'))b.disabled=true})}
function renderSetup(){
 const hand=S.setupHands[S.p],id=selected?.market,d=id===undefined?null:CARDS[id];
 $('#app').innerHTML='<div class="turnbar"><div><span class="phase">SETUP · PLAYER '+(S.p+1)+' OF 2</span><h2>Prepare your cards, '+NAMES[S.p]+'.</h2><p>Draw 4 cards, play 2, and discard the other 2.</p></div><span class="badge">'+S.setupPlayed+' / 2 played</span></div><div class="layout"><section class="table"><div class="sectionhead"><h2>Your starting hand</h2><span>Choose '+(2-S.setupPlayed)+' more card'+(S.setupPlayed?'':'s')+'</span></div><div class="market setup-hand">'+hand.map(id=>cardHTML(id)).join('')+'</div><div class="sectionhead"><h2>Your timer</h2></div>'+track(S.p)+'</section><aside><span class="eyebrow">BEFORE THE FIRST TURN</span><h2>Choose your 2 cards</h2><p>Each card goes on your timer at its time cost, or the next higher available position. Each tile holds at most 2 cards. After your second choice, the 2 remaining cards are automatically discarded.</p>'+(d&&hand.includes(id)?'<div class="selectedDetail"><h3>'+esc(d.name)+'</h3><p>'+esc(description(d))+'</p><p>'+placementText(id)+'</p><button class="primary" onclick="run(async()=>setupPlay('+id+'))" '+(!canRecruit(id)?'disabled':'')+'>Play on timer · '+(timerSlot(S.p,cost(id,S.p))??'full')+'</button></div>':'<p class="notice">Select a card from your starting hand.</p>')+'<div class="log">'+S.log.slice(0,4).map(l=>'<p>'+esc(l)+'</p>').join('')+'</div><button onclick="undo()" '+(!history.length||busy?'disabled':'')+'>↶ Undo last action</button></aside></div>';
 if(busy)$('#app').querySelectorAll('button').forEach(b=>b.disabled=true);
}
function placementText(id){const base=cost(id,S.p),actual=timerSlot(S.p,base);return actual===null?'No free slot at time '+base+' or higher.':actual===base?'Enters at time <b>'+actual+'</b>':'Time '+base+' is full. Enters at time <b>'+actual+'</b>.'}
function side(){let h='';if(S.phase==='slide')h='<p>The tile at position 1 exits. Insert the outside tile at position 5: all the others advance.</p>';if(S.phase==='action'){let f=S.players[S.p].forced;h='<p>Each tile holds 2 cards. Start at the time cost; if full, use the next available higher position, up to 5. If none is free, the card cannot be played.</p>'+(f?'<p class="notice">Manipulator requires: '+(f==='recruit'?'take a card.':'accelerate cards.')+'</p>':'')+'<div class="actions"><button onclick="run(()=>accelerate(accelerated))" '+(!accelerated.length||f==='recruit'?'disabled':'')+'>Accelerate '+accelerated.length+'/2 cards by 2 spaces</button></div><p>Select cards on your timer to accelerate them.</p>';if((f==='accelerate'&&!waiting(S.p).length)||(f==='recruit'&&!S.market.some(id=>canRecruit(id)))||(!waiting(S.p).length&&!S.market.some(id=>canRecruit(id))))h+='<button onclick="run(async()=>spend())">No action available · pass</button>'}
 if(S.phase==='activate')h='<p>Active symbol: <b>'+SIGNS[S.players[S.p].outside]+' '+S.players[S.p].outside+'</b>. Each card may activate once. You may end your turn without using them all.</p>';
 if(selected?.market!==undefined){let id=selected.market,d=CARDS[id];h+='<div class="selectedDetail"><h3>'+esc(d.name)+'</h3><p>'+esc(description(d))+'</p><p>'+placementText(id)+'</p><button class="primary" onclick="run(()=>recruit('+id+'))" '+(S.phase!=='action'||S.players[S.p].forced==='accelerate'||!canRecruit(id)?'disabled':'')+'>Take and prepare</button></div>'}
 if(selected?.uid){let c=find(selected.uid);if(c){h+='<div class="selectedDetail"><h3>'+esc(def(c).name)+'</h3><p>'+esc(description(def(c)))+'</p><div class="actions">';if(eligible(c)){if(creature(c)){h+='<button onclick="use('+c.uid+',\'move\')">Move 1 zone</button><button onclick="use('+c.uid+',\'attack\')" '+(!targets(c).length&&!canCastle(c)?'disabled':'')+'>Attack</button>';if(named(c,'Elf'))h+='<button onclick="use('+c.uid+',\'elf\')">Move and attack</button>';if(color(c,'White')&&has(c.owner,'Medicine school'))h+='<button onclick="use('+c.uid+',\'heal\')">Heal 2 damage</button>'}if(SPECIAL.includes(def(c).name))h+='<button onclick="use('+c.uid+',\'special\')">Use ability</button>'}else h+='<p class="muted">'+(waiting(c.owner).some(x=>x.uid===c.uid)?'Waiting on the timer.':c.used?'Already activated this turn.':'Cannot activate in this phase.')+'</p>';if(named(c,'Mercenary')&&c.owner!==S.p&&S.phase==='action'&&!S.players[S.p].forced)h+='<button onclick="run(()=>steal(find('+c.uid+')))">Recruit Mercenary · 1 action</button>';h+='</div></div>'}}
 return h}
function use(uid,mode){run(()=>activate(find(uid),mode))}
const immediateSlide=slide;
slide=async function(){let track=document.querySelectorAll('.track')[S.p===0?1:0];if(track&&!matchMedia('(prefers-reduced-motion: reduce)').matches){track.classList.add('sliding');await new Promise(r=>setTimeout(r,330))}await immediateSlide()};
function detail(id){$('#modalBody').innerHTML='<h2>'+esc(CARDS[id].name)+'</h2><p>'+esc(description(CARDS[id]))+'</p><p class="muted">Original text: '+esc(CARDS[id].ability||'No additional ability.')+'</p><button onclick="catalog(true)">Back to cards</button>'}
function catalog(already=false){let html='<h2>All 52 cards</h2><p>Imported from the spreadsheet. Displayed costs include the current player’s discounts.</p><div class="catalog">'+CARDS.map(d=>cardHTML(d.id,false)).join('')+'</div>';if(already)$('#modalBody').innerHTML=html;else modal(html)}
function showRules(){modal("<h2>How to play</h2><p><b>Setup.</b> Before the first turn, each player draws 4 cards, plays 2 onto their timer at their normal time cost, and discards the other 2. Jade chooses first, then Amber. Reveal the shared market after both players finish setup. Jade takes the first turn. Starting cards leave the timer following the normal rules.</p><ol><li><b>Slide.</b> Insert the outside tile at time 5. The tile at time 1 exits: its cards enter your home zone. Spells resolve and are discarded. The exiting symbol becomes active.</li><li><b>Take an action.</b> Take one of the 5 shared market cards and place it at its time cost, or advance each of 1 or 2 cards on your timer by 2 spaces. Cards that exit enter play immediately.</li><li><b>Activate.</b> Each of your cards matching the active symbol may act once. Creatures may move one zone, attack, or use an ability. Buildings cannot move on the battlefield. You may end your turn without activating every card.</li><li><b>Fight.</b> Attack an enemy card in the same zone, with no counterattack. Damage persists. A card with damage equal to its life goes to the graveyard. From the enemy home zone, you may attack their castle.</li><li><b>Win.</b> Reduce the enemy castle from 10 life to 0, or reach 10 stars on your cards on the battlefield.</li></ol><h3>Timer capacity</h3><p>Each time tile holds at most 2 cards. When placing a card, start at its required position and check higher numbers until a slot is free (for example, 3, then 4, then 5). If none is free, a voluntary play is blocked without spending the card or action. The same limit applies to setup and abilities. An accelerated card uses the first free position at or above its destination; if blocked, it may stay where it was. Phenix stays in the graveyard if it cannot return at times 3–5.</p><h3>Provisional prototype rules</h3><p>One copy of each of the 52 named cards. The shared market refills immediately. Resolved spells and cards discarded during setup are reshuffled when the deck runs out. Destroyed cards stay in the graveyard. Both timers start with Fast, Medium, Fast, Slow, Medium, with Fast outside. Creatures may move in either direction.</p><p>Selective bombing costs 4. Magnetic force is Slow; Catapult is Fast. Hospital heals 1 at the start of your turn. The four unnamed rows are excluded. Missing stars count as 0; the minimum cost is 1. Perm/Ongoing effects are continuous and do not grant normal activations to creatures without a matching symbol.</p><p>Monolith moves up to 2 creatures by one zone; buildings stay still. Mystical force activates only your own creatures. Outpost targets an enemy card; Temple heals a friendly creature. School of Magic remains effective while its source is on the battlefield. Saboteur requires an activation in the same zone as the building. Apprentice cannot activate another Apprentice, to prevent infinite loops. These interpretations can be revised after playtesting.</p><p><b>Controls:</b> select a market card to prepare it; select up to two cards on your timer to accelerate them; select a highlighted battlefield card to choose its action. Undo restores the last complete action. The game is local to this browser.</p>")}
render();
save();
